CREATE TYPE "Role" AS ENUM ('ADMIN', 'STAFF', 'CLIENT');
CREATE TYPE "ReservationStatus" AS ENUM ('PENDING', 'CONFIRMED', 'CANCELLED', 'COMPLETED');
CREATE TYPE "OrderStatus" AS ENUM ('NEW', 'PREPARING', 'READY', 'PAID', 'CANCELLED');
CREATE TABLE "User" ("id" SERIAL PRIMARY KEY, "name" TEXT NOT NULL, "email" TEXT NOT NULL UNIQUE, "password" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'CLIENT', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "RestaurantTable" ("id" SERIAL PRIMARY KEY, "number" INTEGER NOT NULL UNIQUE, "seats" INTEGER NOT NULL, "description" TEXT, "active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "MenuItem" ("id" SERIAL PRIMARY KEY, "name" TEXT NOT NULL, "description" TEXT, "category" TEXT NOT NULL, "price" DECIMAL(10,2) NOT NULL, "available" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Reservation" ("id" SERIAL PRIMARY KEY, "userId" INTEGER NOT NULL REFERENCES "User"("id"), "tableId" INTEGER NOT NULL REFERENCES "RestaurantTable"("id"), "startAt" TIMESTAMP(3) NOT NULL, "endAt" TIMESTAMP(3) NOT NULL, "guests" INTEGER NOT NULL, "comment" TEXT, "status" "ReservationStatus" NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Reservation_tableId_startAt_endAt_idx" ON "Reservation"("tableId","startAt","endAt");
CREATE TABLE "Order" ("id" SERIAL PRIMARY KEY, "userId" INTEGER NOT NULL REFERENCES "User"("id"), "status" "OrderStatus" NOT NULL DEFAULT 'NEW', "total" DECIMAL(10,2) NOT NULL, "note" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "OrderItem" ("id" SERIAL PRIMARY KEY, "orderId" INTEGER NOT NULL REFERENCES "Order"("id") ON DELETE CASCADE, "menuItemId" INTEGER NOT NULL REFERENCES "MenuItem"("id"), "quantity" INTEGER NOT NULL, "unitPrice" DECIMAL(10,2) NOT NULL);
